[{"locate_evidence": "quote and locator found", "located": true, "locator": "/questions/1", "path": "input/question_set.json", "quote": "{
      "key": "q2_hft_cost_calculation",
      "question": "For a high-frequency trading team with more than 20,000 daily orders, what are the specific numerical amounts of the flow fee and cancellation fee in the provided rules?",
      "allowed_conclusions": [
        "Yes",
        "No",
        "Unknown"
      ]
    }", "sha256": "95f0c98b68c9bca2a4a117992b5cc881e501f73e24fa672da48ccf71c1482476"}, {"locate_evidence": "quote and locator found", "located": true, "locator": "lines:112-116", "path": "input/extracted_text/程序化交易管理实施细则.txt", "quote": "第三十五条 本所对高频交易实施重点监管。投资者进行高频交易发生异常交易行为的，本所可以按规定从严从重采取自律管理措施，并要求会员加强相关客户交易行为管理。
第三十六条 会员应当加强对高频交易的实时监控。投资者进行高频交易可能出现本细则第十八条规定的异常交易行为的，会员应当按照委托协议等约定立即采取有效控制及处置措施，避免影响本所系统安全或者正常交易秩序。
使用交易单元的其他机构应当识别自身存在高频交易情形的账户，并进行严格管理。
第三十七条 本所可以对高频交易实施差异化收费，根据申报、撤单的笔数和频率等指标设置收费标准，加收流量费和撤单费等费用。具体收费标准由本所另行规定。
会员应当加强收费管理，确保差异化费用成本由存在高频交易的投资者承担。", "sha256": "46d3b5beaf2eb6334ded0cfd02be87fc3c8b165076faee785fc2d3c019bf332c"}, {"locate_evidence": "quote and locator found", "located": true, "locator": "lines:108-114", "path": "input/extracted_text/1-2_填报说明.txt", "quote": "投资者已经达到或者根据策略类型和系统情况综合预判可能达到的单日最高申报笔数所在区间，在下列区间选择1项：
（一）25000笔及以上;
（二）20000笔至24999笔;
（三）15000笔至19999笔;
（四）10000笔至14999笔;
（五）10000笔以下。
如选择第一项或者第二项且不符合《指引》第七条规定的豁免情形，须填写“高频交易系统服务器所在地”，并上传高频交易系统测试报告和高频交易系统发生故障时的应急方案。", "sha256": "66b4ac87a58daaf0469b82dc9d61c2b29c47981e3accc89953f1125aef020d46"}, {"locate_evidence": "quote and locator found", "located": true, "locator": "/7/citation_aliases", "path": "input/document_manifest.json", "quote": "[
      "上海证券交易所程序化交易管理实施细则"
    ]", "sha256": "6adc29244619a761e13670595e130100b7a9bae8d3e9328e97027c9fa89e3e81"}]

[{"locate_evidence": "quote and locator found", "located": true, "locator": "/manifest_required_keys", "path": "input/starter_project/output_contract.json", "quote": "[
    "python_version",
    "platform",
    "rubric_version"
  ]", "sha256": "772eab9c44112f19c359b8367a166512aa2d80112cc0583204eb511ef9cb5fa7"}, {"locate_evidence": "quote and locator found", "located": true, "locator": "lines:35-40", "path": "input/starter_project/grading_scaffold.py", "quote": "def build_manifest() -> dict[str, str]:
    return {
        "python_version": sys.version.split()[0],
        "platform": platform.platform(),
        "rubric_version": "starter-scaffold",
    }", "sha256": "52dc52ec222f901588247dfaad54bf302bd348664db3a08990d2f944a817d01c"}]

[{"locate_evidence": "quote and locator found", "located": true, "locator": "/problems", "path": "input/released/rubric.json", "quote": "{
    "1a": {
      "points": 2.0,
      "description": "Correct explicit update with the second-difference term."
    },
    "1b": {
      "points": 3.0,
      "description": "Correct stability restriction dt <= dx^2 / (2 kappa) and dt_max = 0.01."
    },
    "2a": {
      "points": 2.0,
      "description": "Correct weak form after integration by parts."
    },
    "2b": {
      "points": 3.0,
      "description": "Correct bilinear form, linear functional, and test space H_0^1(0,1)."
    }
  }", "sha256": "39b57a386058eb94db715583aa36513276601262170afcb3f704196e91808d82"}, {"locate_evidence": "quote and locator found", "located": true, "locator": "lines:10-15", "path": "input/starter_project/README.md", "quote": "It cannot:
- compute the correct rubric-aligned grades for you
- infer the correct error tags automatically
- write full-score feedback by itself

Running `python run_submission.py --output-dir <dir>` produces a structurally valid baseline submission that is expected to score below `1.0`.", "sha256": "4323fa220d6e9e5264b2863396ea1571fc8b907b272f1b7af131d4664941f030"}]

[{"locate_evidence": "quote and locator found", "located": true, "locator": "lines:35-40", "path": "input/starter_project/grading_scaffold.py", "quote": "def build_manifest() -> dict[str, str]:
    return {
        "python_version": sys.version.split()[0],
        "platform": platform.platform(),
        "rubric_version": "starter-scaffold",
    }", "sha256": "52dc52ec222f901588247dfaad54bf302bd348664db3a08990d2f944a817d01c"}, {"locate_evidence": "quote and locator found", "located": true, "locator": "lines:1-1", "path": "software/README.txt", "quote": "Use the task-local `software/python` wrapper on the Linux VM to script the grading workflow. The wrapper `exec`s the preinstalled `/usr/bin/python` (Python 3.10.12). No extra runtime install is required.", "sha256": "fb3f65ce4257b8a6f6fac751549b70c66cd239c000651e82f94fdd497eb1ce02"}]

[{"locate_evidence": "quote and locator found", "located": true, "locator": "/problems", "path": "input/released/rubric.json", "quote": "{
    "1a": {
      "points": 2.0,
      "description": "Correct explicit update with the second-difference term."
    },
    "1b": {
      "points": 3.0,
      "description": "Correct stability restriction dt <= dx^2 / (2 kappa) and dt_max = 0.01."
    },
    "2a": {
      "points": 2.0,
      "description": "Correct weak form after integration by parts."
    },
    "2b": {
      "points": 3.0,
      "description": "Correct bilinear form, linear functional, and test space H_0^1(0,1)."
    }
  }", "sha256": "39b57a386058eb94db715583aa36513276601262170afcb3f704196e91808d82"}, {"locate_evidence": "quote and locator found", "located": true, "locator": "lines:3-6", "path": "input/released/grading_protocol.md", "quote": "1. Read the problem set, rubric, and solution key.
2. Grade each anonymized submission part by part.
3. Assign major-error tags when the rubric indicates a conceptual mistake.
4. Produce concise student-facing feedback and a common-mistakes summary.", "sha256": "42a53933612d0e221bf5502ba6ccec61fd85d808cf6dc38f16f9a7a3cb5198eb"}]

[{"locate_evidence": "quote and locator found", "located": true, "locator": "/feedback_style", "path": "input/released/rubric.json", "quote": "{
    "max_words_per_student": 70,
    "tone": "brief, constructive, rubric-based"
  }", "sha256": "39b57a386058eb94db715583aa36513276601262170afcb3f704196e91808d82"}, {"locate_evidence": "quote and locator found", "located": true, "locator": "lines:4-6", "path": "input/released/grading_protocol.md", "quote": "2. Grade each anonymized submission part by part.
3. Assign major-error tags when the rubric indicates a conceptual mistake.
4. Produce concise student-facing feedback and a common-mistakes summary.", "sha256": "42a53933612d0e221bf5502ba6ccec61fd85d808cf6dc38f16f9a7a3cb5198eb"}]

evidence:
checker audit: The substantive validation path in checks/submission_csv_contract.py matches the stated structural requirement: it checks VERIFIER_OUTPUT/submission.csv with is_file(); reads input/locations.csv; constructs all 53 × 4 expected metadata tuples using reference date 2024-12-14 and the four published horizon/date mappings; requires the exact ordered header; checks 212 data rows, eight fields per row, missing and unexpected keys, and duplicate keys; and applies the regex [0-9]+ followed by integer comparison lower <= point <= upper to all three forecast fields. Thus public_recompute honestly describes the computation and no task-native validator is being replaced. However, the checker emits status values 'passed' and 'failed'. Fixture preflight shows that both the valid and invalid executions are rejected as having an invalid status, producing valid_status='error', invalid_status='error', and checker_reproducible=false. The valid fixture reaches the no-evidence branch at lines 59–61 and prints status='passed'; the invalid fixture reaches the bad_order branch at lines 55–57 and prints status='failed'. Because neither emitted status is accepted by the test protocol, the staged script does not function as an executable blocking check despite performing the correct underlying recomputation.; fixture preflight: environment: isolated Python probe passed; valid fixture: run 1: ValueError: test stdout has an invalid status or empty evidence; run 2: ValueError: test stdout has an invalid status or empty evidence; captured run 1 stdout='{"analysis": null, "evidence": ["submission.csv satisfies the complete public CSV contract"], "observed": {"columns": ["reference_date", "location", "location_name", "horizon", "target_end_date", "point", "lower_95", "upper_95"], "duplicate_key_count": 0, "expected_row_count": 212, "invalid_interval_order_rows": 0, "invalid_nonnegative_integer_rows": 0, "missing_key_count": 0, "row_count": 212, "submission_exists": true, "unexpected_key_count": 0}, "status": "passed"}
' stderr=''; captured run 2 stdout='{"analysis": null, "evidence": ["submission.csv satisfies the complete public CSV contract"], "observed": {"columns": ["reference_date", "location", "location_name", "horizon", "target_end_date", "point", "lower_95", "upper_95"], "duplicate_key_count": 0, "expected_row_count": 212, "invalid_interval_order_rows": 0, "invalid_nonnegative_integer_rows": 0, "missing_key_count": 0, "row_count": 212, "submission_exists": true, "unexpected_key_count": 0}, "status": "passed"}
' stderr=''; invalid fixture: run 1: ValueError: test stdout has an invalid status or empty evidence; run 2: ValueError: test stdout has an invalid status or empty evidence; captured run 1 stdout='{"analysis": null, "evidence": ["rows violating lower_95 <= point <= upper_95 (first 20): [2]"], "observed": {"columns": ["reference_date", "location", "location_name", "horizon", "target_end_date", "point", "lower_95", "upper_95"], "duplicate_key_count": 0, "expected_row_count": 212, "invalid_interval_order_rows": 1, "invalid_nonnegative_integer_rows": 0, "missing_key_count": 0, "row_count": 212, "submission_exists": true, "unexpected_key_count": 0}, "status": "failed"}
' stderr=''; captured run 2 stdout='{"analysis": null, "evidence": ["rows violating lower_95 <= point <= upper_95 (first 20): [2]"], "observed": {"columns": ["reference_date", "location", "location_name", "horizon", "target_end_date", "point", "lower_95", "upper_95"], "duplicate_key_count": 0, "expected_row_count": 212, "invalid_interval_order_rows": 1, "invalid_nonnegative_integer_rows": 0, "missing_key_count": 0, "row_count": 212, "submission_exists": true, "unexpected_key_count": 0}, "status": "failed"}
' stderr=''
